import type { ITheme } from '@xterm/xterm'
import type { CreateSessionResult, LaunchOptions } from '@shared/types'
import { TerminalHost } from './host'

/**
 * Registry of active terminals.
 *
 * The PANE id is generated by the renderer and is decoupled from the PTY id,
 * which is minted in the main process. Keeping them distinct means the pane
 * exists (and can be rendered and measured) before the process is spawned:
 * the PTY can spawn with correct dimensions, and moving a pane in the layout tree
 * never changes its React key and never destroys its buffer.
 */
const hosts = new Map<string, TerminalHost>()
const ptyByPane = new Map<string, string>()
const paneByPty = new Map<string, string>()
const starting = new Set<string>()
/**
 * Panes closed while their PTY was still spawning. They cannot be terminated
 * immediately because the process does not exist yet: the cancellation is
 * noted here and handled by `ensureSession` as soon as creation returns.
 */
const cancelled = new Set<string>()

let wired = false

export interface SessionEvents {
  onExit: (paneId: string, exitCode: number) => void
  onTitle: (paneId: string, title: string) => void
}

let events: SessionEvents | null = null

export function setSessionEvents(next: SessionEvents | null): void {
  events = next
}

/** Connects main -> renderer PTY events to the registry once. */
export function wireTerminalEvents(): () => void {
  if (wired) return () => undefined
  wired = true

  const offData = window.cm.pty.onData(({ id, data }) => {
    const paneId = paneByPty.get(id)
    if (paneId) hosts.get(paneId)?.write(data)
  })

  const offExit = window.cm.pty.onExit(({ id, exitCode }) => {
    const paneId = paneByPty.get(id)
    if (!paneId) return
    hosts
      .get(paneId)
      ?.writeAppMessage(`— shell exited (code ${exitCode}). Pane remains open.`)
    events?.onExit(paneId, exitCode)
  })

  return () => {
    offData()
    offExit()
    wired = false
  }
}

export function hostFor(paneId: string): TerminalHost | undefined {
  return hosts.get(paneId)
}

export function isStarted(paneId: string): boolean {
  return hosts.has(paneId) || starting.has(paneId)
}

/**
 * Creates the terminal, measures it, and only then spawns the PTY with
 * correct dimensions: otherwise Claude would start at 80x24 and trigger a redraw.
 * Idempotent, so double rendering does not spawn duplicate processes.
 */
export interface EnsureOptions {
  /**
   * Checked when PTY is ready: focus is applied only if the pane is still
   * the active one. Between request and response the user may have selected another pane.
   */
  shouldFocus?: () => boolean
}

export async function ensureSession(
  paneId: string,
  slot: HTMLElement,
  opts: LaunchOptions,
  options: EnsureOptions = {}
): Promise<CreateSessionResult | null> {
  const existing = hosts.get(paneId)
  if (existing) {
    existing.attach(slot)
    return null
  }
  if (starting.has(paneId)) return null
  starting.add(paneId)

  const host = new TerminalHost(currentTerminalTheme ?? undefined)
  host.onTitle = (title) => events?.onTitle(paneId, title)
  host.attach(slot)
  host.fitNow()

  try {
    const result = await window.cm.pty.create(opts)

    // The pane may have been closed while the process was spawning. Omitting
    // it from internal maps is not enough: PowerShell and claude processes
    // are already running and would never be terminated.
    if (cancelled.has(paneId)) {
      host.dispose()
      await window.cm.pty.kill(result.id)
      return null
    }

    hosts.set(paneId, host)
    ptyByPane.set(paneId, result.id)
    paneByPty.set(result.id, paneId)
    host.bind(result.id)
    // A newly created pane is typically the active one, but focus may have
    // moved elsewhere: stealing focus would route input to the wrong terminal.
    if (options.shouldFocus?.() ?? true) host.focus()
    return result
  } catch (err) {
    host.dispose()
    throw err
  } finally {
    starting.delete(paneId)
    cancelled.delete(paneId)
  }
}

/** Reattaches an existing terminal to a new DOM slot. */
export function attachTo(paneId: string, slot: HTMLElement): void {
  hosts.get(paneId)?.attach(slot)
}

export function focusPane(paneId: string): void {
  hosts.get(paneId)?.focus()
}

/** Searches pane scrollback; returns false if no match. */
export function searchPane(
  paneId: string,
  query: string,
  direction: 'next' | 'previous'
): boolean {
  return hosts.get(paneId)?.search(query, direction) ?? false
}

/** Clears search highlights upon search bar close. */
export function clearSearch(paneId: string): void {
  hosts.get(paneId)?.clearSearch()
}

/** Remeasures terminal: call after pane geometry change. */
export function refit(paneId: string): void {
  hosts.get(paneId)?.fitNow()
}

/**
 * Freezes measurement for all terminals for the duration of a layout animation,
 * and resumes at the end with a single remeasurement.
 */
export function setFitSuspendedAll(suspended: boolean): void {
  for (const host of hosts.values()) host.setFitSuspended(suspended)
}

/**
 * Current terminal palette.
 *
 * Must be retained here and not just applied to existing terminals:
 * a pane opened after a theme change must spawn with correct colors,
 * avoiding a flash of the default palette.
 */
let currentTerminalTheme: ITheme | null = null

export function applyThemeToTerminals(theme: ITheme): void {
  currentTerminalTheme = theme
  for (const host of hosts.values()) host.setTheme(theme)
}

export function terminalTheme(): ITheme | null {
  return currentTerminalTheme
}

export async function destroySession(paneId: string): Promise<void> {
  // Spawn in flight: nothing to terminate yet, record cancellation
  // so ensureSession can clean up when PTY creation finishes.
  if (starting.has(paneId)) {
    cancelled.add(paneId)
    return
  }

  const host = hosts.get(paneId)
  const ptyId = ptyByPane.get(paneId)

  hosts.delete(paneId)
  ptyByPane.delete(paneId)
  if (ptyId) paneByPty.delete(ptyId)

  host?.dispose()
  if (ptyId) await window.cm.pty.kill(ptyId)
}

export function disposeAllHosts(): void {
  for (const host of hosts.values()) host.dispose()
  hosts.clear()
  ptyByPane.clear()
  paneByPty.clear()
  starting.clear()
  cancelled.clear()
}
